     * Build an PlantCSVReader and initializes field.
     */
    public PlantCSVReader ()
    {
        errorThrower = new ErrorThrower();
        name = null;
        maximumTemperature = 0;
        minimumTemperature = 0;
        nutritionalValue = 0;
        reproductionProbability = 0;
        maxHealth = 0;
